alter table public.sgsti_notification_deliveries drop constraint if exists sgsti_notification_deliveries_notification_type_check;
alter table public.sgsti_notification_deliveries add constraint sgsti_notification_deliveries_notification_type_check check(notification_type in ('ACTIVITY_REMINDER','ACTIVITY_OVERDUE','APPROVAL_PENDING','ASSURANCE_REQUEST'));

create or replace function public.create_sgsti_assurance_request(target_organization_id uuid,target_control_id uuid,target_title text,target_requirement text,target_note text,target_responsible_id uuid,target_due_at date) returns uuid language plpgsql security definer set search_path=public as $$
declare request_id uuid; event_id uuid;
begin
 if not (public.has_sgsti_role(target_organization_id,'AUDITOR') or public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[])) then raise exception 'SGSTI_ASSURANCE_NOT_AUTHORIZED'; end if;
 if coalesce(length(trim(target_title)),0) not between 5 and 240 or coalesce(length(trim(target_note)),0) not between 10 and 10000 or target_due_at<current_date-1 then raise exception 'SGSTI_ASSURANCE_INVALID_INPUT'; end if;
 if not exists(select 1 from public.user_roles where organization_id=target_organization_id and user_id=target_responsible_id) then raise exception 'SGSTI_ASSURANCE_RESPONSIBLE_NOT_MEMBER'; end if;
 insert into public.sgsti_assurance_requests(organization_id,control_id,title,requirement_reference,request_note,responsible_id,due_at,requested_by) values(target_organization_id,target_control_id,trim(target_title),nullif(trim(target_requirement),''),trim(target_note),target_responsible_id,target_due_at,auth.uid()) returning id into request_id;
 insert into public.outbox_events(organization_id,event_type,aggregate_type,aggregate_id,payload,idempotency_key) values(target_organization_id,'SGSTI_ASSURANCE_NOTIFICATION','SGSTI_ASSURANCE_REQUEST',request_id,jsonb_build_object('recipientId',target_responsible_id,'notificationType','ASSURANCE_REQUEST','title','Novo pedido de evidência SGSTI','body',format('%s. Prazo: %s.',trim(target_title),to_char(target_due_at,'DD/MM/YYYY')),'targetPath','/portal/sgsti/assurance'),format('SGSTI_ASSURANCE:%s:CREATED',request_id)) returning id into event_id;
 insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(target_organization_id,auth.uid(),'SGSTI_ASSURANCE_REQUEST_CREATED','sgsti_assurance_request',request_id,jsonb_build_object('responsible_id',target_responsible_id,'due_at',target_due_at,'outbox_event_id',event_id),'WEB'); return request_id;
end; $$;

create or replace function public.deliver_sgsti_notification(target_event_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare event_record public.outbox_events%rowtype; recipient uuid; notification_kind text; notification_title text; notification_body text; notification_path text;
begin
 perform public.assert_outbox_worker(); select * into event_record from public.outbox_events where id=target_event_id and event_type in ('SGSTI_REMINDER','SGSTI_ASSURANCE_NOTIFICATION'); if event_record.id is null then raise exception 'SGSTI_NOTIFICATION_EVENT_NOT_FOUND'; end if;
 recipient:=(event_record.payload->>'recipientId')::uuid;notification_kind:=event_record.payload->>'notificationType';notification_title:=event_record.payload->>'title';notification_body:=event_record.payload->>'body';notification_path:=event_record.payload->>'targetPath';
 if recipient is null or notification_kind not in ('ACTIVITY_REMINDER','ACTIVITY_OVERDUE','APPROVAL_PENDING','ASSURANCE_REQUEST') or coalesce(length(trim(notification_title)),0)<3 or coalesce(length(trim(notification_body)),0)<3 or notification_path not like '/portal/%' then raise exception 'SGSTI_NOTIFICATION_INVALID_PAYLOAD'; end if;
 insert into public.sgsti_notification_deliveries(outbox_event_id,organization_id,recipient_id,notification_type,title,body,target_path) values(event_record.id,event_record.organization_id,recipient,notification_kind,notification_title,notification_body,notification_path) on conflict(outbox_event_id) do nothing;
 insert into public.audit_logs(organization_id,action,entity_type,entity_id,after_value,source) values(event_record.organization_id,'SGSTI_NOTIFICATION_DELIVERED','sgsti_notification',target_event_id,jsonb_build_object('recipient_id',recipient,'notification_type',notification_kind),'WORKER');
end; $$;

create or replace function public.claim_sgsti_notification_events(target_limit integer default 20,target_lock_seconds integer default 300) returns table(id uuid,organization_id uuid,event_type text,aggregate_type text,aggregate_id uuid,payload jsonb,attempts integer,correlation_id uuid) language plpgsql security definer set search_path=public as $$
begin perform public.assert_outbox_worker();if target_limit not between 1 and 100 or target_lock_seconds not between 30 and 3600 then raise exception 'OUTBOX_INVALID_CLAIM_OPTIONS';end if;return query with candidates as(select event.id from public.outbox_events event where event.available_at<=now() and event.status in('PENDING','PROCESSING') and event.event_type in('SGSTI_REMINDER','SGSTI_ASSURANCE_NOTIFICATION') order by event.created_at for update skip locked limit target_limit),claimed as(update public.outbox_events event set status='PROCESSING',attempts=event.attempts+1,available_at=now()+make_interval(secs=>target_lock_seconds),last_error=null from candidates where event.id=candidates.id returning event.*),recorded as(insert into public.outbox_event_attempts(outbox_event_id,attempt_number,outcome) select id,attempts,'STARTED' from claimed) select claimed.id,claimed.organization_id,claimed.event_type,claimed.aggregate_type,claimed.aggregate_id,claimed.payload,claimed.attempts,claimed.correlation_id from claimed;end; $$;
revoke all on function public.claim_sgsti_notification_events(integer,integer) from public,authenticated,anon;grant execute on function public.claim_sgsti_notification_events(integer,integer) to service_role;
